package com.bplus.share;
import android.app.*;import android.content.*;import android.net.nsd.*;import android.net.wifi.WifiManager;import android.os.*;import android.widget.*;import org.json.*;import java.util.*;import java.util.concurrent.*;
public class NearbyActivity extends Activity {
 private final java.util.ArrayList<AlertDialog> openDialogs=new java.util.ArrayList<>();private NsdManager nsd;private NsdManager.RegistrationListener registration;private NsdManager.DiscoveryListener discovery;private WifiManager.MulticastLock lock;private LinearLayout list;private TextView state;private final Handler handler=new Handler();private final java.util.concurrent.ThreadPoolExecutor worker=new java.util.concurrent.ThreadPoolExecutor(3,3,0L,TimeUnit.MILLISECONDS,new ArrayBlockingQueue<Runnable>(16));private final ExecutorService pairWorker=Executors.newSingleThreadExecutor();private int screenGeneration;private final Map<String,TextView> pairButtons=new HashMap<>();private NearbyDiscovery scanner;private volatile boolean active;private boolean requesting,completing;private NearbyGate.Request accepted;private final Set<String> found=new HashSet<>(),dialogs=new HashSet<>();private volatile String outgoingId="",outgoingSecret="",outgoingIp="";
 private final Runnable autoRefresh=new Runnable(){public void run(){if(!active)return;if(accepted==null&&outgoingId.isEmpty()&&!requesting&&!completing&&scanner!=null)scanner.maintain(false);handler.postDelayed(this,20000);}};
 private final Runnable poll=new Runnable(){public void run(){if(!active||completing)return;if(accepted!=null){int outcome=NearbyCompletion.state(accepted.status,accepted.expires,System.currentTimeMillis(),Store.peerById(accepted.profile.optString("id"))!=null);if(outcome==1){paired(accepted.profile.optString("name"));return;}if(outcome==-1){accepted=null;state.setText(getString(R.string.nearby_confirm_timeout));updateButtons();}}if(accepted==null&&!requesting&&outgoingId.isEmpty())for(NearbyGate.Request r:Nearby.gate.pending(System.currentTimeMillis()))if(Repair.matches(Repair.target(NearbyActivity.this),r.profile.optString("id"))&&dialogs.add(r.id)){incoming(r);break;}handler.postDelayed(this,800);}};
 @Override public void onCreate(Bundle b){super.onCreate(b);Ui.applyLocale(this);Ui.applyTheme(this);Profile.init();LinearLayout root=Ui.col(this);root.setBackgroundColor(Ui.bg);root.addView(Ui.topBar(this,getString(R.string.nearby_title),true,null));state=Ui.t(this,Repair.target(this).isEmpty()?getString(R.string.nearby_notice):getString(R.string.repair_wait,getIntent().getStringExtra(Repair.NAME)),13,Ui.dim,App.cairoSB);Ui.pad(state,20,14,20,14,this);root.addView(state);TextView automatic=Ui.t(this,getString(R.string.nearby_auto_refresh_note),12,Ui.accent,App.cairoSB);Ui.pad(automatic,20,0,20,12,this);root.addView(automatic);ScrollView sc=new ScrollView(this);list=Ui.col(this);Ui.pad(list,20,0,20,20,this);sc.addView(list);root.addView(sc,Ui.lpW1());TextView qr=Ui.ghost(this,getString(R.string.qr_fallback));Ui.pad(qr,20,16,20,16,this);LinearLayout footer=Ui.col(this);Ui.pad(footer,20,16,20,20,this);footer.addView(qr,Ui.lp(-1,-2));root.addView(footer,Ui.lp(-1,-2));qr.setOnClickListener(v->startActivity(new Intent(this,DevicesActivity.class)));LinearLayout tools=Ui.row(this);TextView refresh=Ui.ghost(this,getString(R.string.nearby_refresh));TextView copy=Ui.ghost(this,getString(R.string.copy_details));LinearLayout.LayoutParams refreshLp=Ui.lpw(1);refreshLp.setMarginEnd(Ui.dp(this,12));tools.addView(refresh,refreshLp);if(DeveloperMode.enabled())tools.addView(copy,Ui.lpw(1));LinearLayout.LayoutParams toolsLp=Ui.lp(-1,-2);toolsLp.topMargin=Ui.dp(this,12);footer.addView(tools,toolsLp);refresh.setOnClickListener(v->{if(accepted!=null||!outgoingId.isEmpty()||requesting||completing)return;found.clear();pairButtons.clear();list.removeAllViews();if(scanner!=null)scanner.refresh();});copy.setOnClickListener(v->{if(scanner!=null)PairUi.copy(this,scanner.details());});setContentView(root);}
 @Override protected void onResume(){super.onResume();TransferService.listen("nearby-confirmed",(type,data)->runOnUiThread(()->checkIncoming()));start();}
 private void start(){getWindow().addFlags(android.view.WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);final int gen=++screenGeneration;active=true;completing=false;accepted=null;Nearby.gate.visible(true);handler.post(poll);scanner=new NearbyDiscovery(this,new NearbyDiscovery.View(){public void address(String ip){final NearbyDiscovery owner=scanner;try{worker.execute(()->load(ip,gen,owner));}catch(RejectedExecutionException full){owner.diagnostic("Profile queue full "+ip);owner.profileResult(ip,false);}}public void state(int message){if(active&&accepted==null&&outgoingId.isEmpty()&&!requesting&&!completing)state.setText(Repair.target(NearbyActivity.this).isEmpty()?getString(message):getString(R.string.repair_wait,getIntent().getStringExtra(Repair.NAME)));}});scanner.start();handler.postDelayed(autoRefresh,20000);}
 private void showError(String e){runOnUiThread(()->state.setText(getString(R.string.nearby_failed)+"\n"+e));}
 private void load(String ip,int gen,NearbyDiscovery owner){long started=SystemClock.elapsedRealtime();try{if(!active||gen!=screenGeneration)return;owner.diagnostic("Profile started "+ip);JSONObject profile=Profile.clean(Nearby.profile(ip));if(!active||gen!=screenGeneration)return;final JSONObject loaded=profile;owner.profileResult(ip,true);owner.diagnostic("Profile completed "+ip+" elapsed="+(SystemClock.elapsedRealtime()-started)+"ms");if(profile.optString("id").equals(Store.get("deviceId","")))return;if(Store.get("blocked_"+profile.optString("id"),"0").equals("1")||!Repair.matches(Repair.target(this),profile.optString("id")))return;runOnUiThread(()->{if(!active||gen!=screenGeneration||!found.add(loaded.optString("id")))return;LinearLayout row=Ui.row(this);row.addView(Profile.avatar(this,loaded,48));LinearLayout meta=Ui.col(this);Ui.pad(meta,12,12,12,12,this);meta.addView(Ui.t(this,loaded.optString("name"),16,Ui.text,App.cairoB));meta.addView(Ui.t(this,"@"+loaded.optString("username"),12,Ui.dim,App.cairoSB));row.addView(meta,Ui.lpw(1));TextView add=Ui.ghost(this,getString(R.string.request_pair));add.setTextSize(11);add.setMaxWidth(Ui.dp(this,112));row.addView(add);add.setOnClickListener(v->request(ip,loaded));pairButtons.put(loaded.optString("id"),add);list.addView(row);updateButtons();});}catch(Exception error){owner.diagnostic("Profile failed "+ip+" "+error.getClass().getSimpleName()+(error.getMessage()!=null&&error.getMessage().startsWith("Profile HTTP ")?" "+error.getMessage():"")+" elapsed="+(SystemClock.elapsedRealtime()-started)+"ms");owner.profileResult(ip,false);}}
 private void request(String ip,JSONObject profile){if(requesting||completing||accepted!=null||!outgoingId.isEmpty()){android.widget.Toast.makeText(this,getString(R.string.request_wait),0).show();return;}new AppDialog(this).setTitle(getString(R.string.request_pair)).setMessage(profile.optString("name")+"\n@"+profile.optString("username")+"\n"+getString(R.string.identity_notice)).setNegativeButton(getString(R.string.cancel),null).setPositiveButton(getString(R.string.request_pair),(d,n)->{requesting=true;updateButtons();pairWorker.execute(()->{
  String secret=UUID.randomUUID().toString().replace("-","");try{JSONObject body=new JSONObject();body.put("secret",secret);body.put("profile",Profile.local());JSONObject response=Nearby.call(ip,"/nearby/request",body);if(!active){JSONObject end=new JSONObject();end.put("request",response.getString("request"));end.put("secret",secret);Nearby.call(ip,"/nearby/cancel",end);return;}outgoingId=response.getString("request");outgoingSecret=secret;outgoingIp=ip;runOnUiThread(()->pending(profile));}catch(Exception e){showError(e.getMessage());}finally{runOnUiThread(()->{requesting=false;updateButtons();});}
 });}).show();}
 private void pending(JSONObject profile){if(!active){cancel();return;}state.setText(getString(R.string.request_wait)+" · "+profile.optString("name"));AlertDialog dialog=new AppDialog(this).setMessage(getString(R.string.request_wait)).setNegativeButton(getString(R.string.cancel),(d,n)->cancel()).create();dialog.setCancelable(true);dialog.setCanceledOnTouchOutside(true);dialog.setOnCancelListener(d->cancel());openDialogs.add(dialog);dialog.show();String id=outgoingId,secret=outgoingSecret,ip=outgoingIp;
 updateButtons();pairWorker.execute(()->{long deadline=System.currentTimeMillis()+120000;String result="timeout";try{while(active&&outgoingId.equals(id)&&System.currentTimeMillis()<deadline){Thread.sleep(1400);JSONObject b=new JSONObject();b.put("request",id);b.put("secret",secret);JSONObject r=Nearby.call(ip,"/nearby/status",b);String status=r.optString("status");if((status.equals("accepted")||status.equals("paired"))&&active&&outgoingId.equals(id)){JSONObject peer=Profile.clean(r.getJSONObject("profile"));if(!profile.optString("id").equals(peer.optString("id"))||!Repair.matches(Repair.target(this),peer.optString("id")))throw new java.io.IOException("Different device. Pairing refused.");peer.put("token",r.getString("token"));peer.put("ip",ip);peer.put("port",Store.PORT);String epoch=UnpairWire.nearby(id,secret);b.put("pairEpoch",epoch);b.put("token",Store.token());boolean confirmed=status.equals("paired");if(confirmed&&epoch.equals(r.optString("pairEpoch")))peer.put("pairEpoch",epoch);for(int tries=0;!confirmed&&tries<3&&active&&outgoingId.equals(id);tries++){try{JSONObject ack=Nearby.call(ip,"/nearby/confirm",b);confirmed=ack.optString("status").equals("paired");if(epoch.equals(ack.optString("pairEpoch")))peer.put("pairEpoch",epoch);}catch(Exception transientError){if(tries==2)throw transientError;Thread.sleep(500);}}if(!Repair.target(this).isEmpty()&&!epoch.equals(peer.optString("pairEpoch")))throw new java.io.IOException("Fresh pairing epoch not confirmed. Update both apps.");if(!confirmed||!active||!outgoingId.equals(id))throw new java.io.IOException("Pairing was not confirmed");Store.upsertPeer(peer);result="paired";break;}if(!status.equals("pending")){result=status;break;}}}catch(Exception e){result=e.getClass().getSimpleName()+": "+e.getMessage();}String finalResult=result;outgoingId="";runOnUiThread(()->{dialog.dismiss();updateButtons();if(active){if(finalResult.equals("paired"))paired(profile.optString("name"));else state.setText(getString(R.string.request_ended)+" · "+finalResult);}});});}
 private void cancel(){String id=outgoingId,secret=outgoingSecret,ip=outgoingIp;outgoingId="";updateButtons();new Thread(()->{try{JSONObject b=new JSONObject();b.put("request",id);b.put("secret",secret);Nearby.call(ip,"/nearby/cancel",b);}catch(Exception ignored){}}).start();}
 private void incoming(NearbyGate.Request r){LinearLayout box=Ui.col(this);Ui.pad(box,22,14,22,14,this);box.addView(Profile.avatar(this,r.profile,64));box.addView(Ui.t(this,r.profile.optString("name")+"\n@"+r.profile.optString("username"),18,Ui.text,App.cairoB));box.addView(Ui.t(this,getString(R.string.identity_notice)+"\n"+getString(R.string.accept_notice),13,Ui.dim,App.cairoSB));AlertDialog dialog=new AppDialog(this).setTitle(getString(R.string.incoming_request)).setView(box).setPositiveButton(getString(R.string.accept_pair),(d,n)->decide(r,"accepted")).setNegativeButton(getString(R.string.decline_pair),(d,n)->decide(r,"declined")).setNeutralButton(getString(R.string.block_pair),(d,n)->{Store.set("blocked_"+r.profile.optString("id"),"1");decide(r,"blocked");}).setOnCancelListener(d->decide(r,"declined")).create();openDialogs.add(dialog);dialog.show();}
 private void decide(NearbyGate.Request r,String status){try{Nearby.gate.decide(r.id,status,System.currentTimeMillis());if(status.equals("accepted"))accepted=r;updateButtons();state.setText(getString(status.equals("accepted")?R.string.nearby_completing:R.string.request_ended));}catch(Exception e){showError(e.getMessage());}}
 private void updateButtons(){boolean locked=requesting||accepted!=null||!outgoingId.isEmpty()||completing;for(TextView b:pairButtons.values()){b.setEnabled(!locked);b.setAlpha(locked?.45f:1f);b.setText(getString(locked?R.string.request_wait:R.string.request_pair));}}
 private void checkIncoming(){if(!active||completing||accepted==null)return;NearbyGate.Request r=accepted;if(NearbyCompletion.state(r.status,r.expires,System.currentTimeMillis(),Store.peerById(r.profile.optString("id"))!=null)==1)paired(r.profile.optString("name"));}
 private void paired(String name){if(!active||completing)return;completing=true;accepted=null;for(AlertDialog d:openDialogs)d.dismiss();openDialogs.clear();list.removeAllViews();state.setText(getString(R.string.phones_paired));LinearLayout card=Ui.col(this);card.setBackground(Ui.roundBorder(Ui.card,Ui.border,16,this));Ui.pad(card,24,26,24,26,this);TextView check=Ui.t(this,"✓",44,Ui.accent,App.cairoB);check.setGravity(android.view.Gravity.CENTER);card.addView(check);TextView title=Ui.t(this,getString(R.string.phones_paired),22,Ui.text,App.cairoB);title.setGravity(android.view.Gravity.CENTER);card.addView(title);TextView device=Ui.t(this,name,17,Ui.text,App.cairoSB);device.setGravity(android.view.Gravity.CENTER);card.addView(device);card.addView(Ui.sub(this,getString(R.string.nearby_returning)));list.addView(card);handler.postDelayed(()->{if(active&&!isFinishing()){startActivity(new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP));finish();}},1400);}
 @Override protected void onPause(){getWindow().clearFlags(android.view.WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);screenGeneration++;worker.getQueue().clear();TransferService.unlisten("nearby-confirmed");active=false;accepted=null;completing=false;for(AlertDialog d:openDialogs)d.dismiss();openDialogs.clear();cancel();Nearby.gate.visible(false);handler.removeCallbacksAndMessages(null);if(scanner!=null)scanner.stop();try{if(discovery!=null)nsd.stopServiceDiscovery(discovery);}catch(Exception ignored){}try{if(registration!=null)nsd.unregisterService(registration);}catch(Exception ignored){}try{if(lock!=null&&lock.isHeld())lock.release();}catch(Exception ignored){}found.clear();pairButtons.clear();list.removeAllViews();super.onPause();}
 @Override protected void onDestroy(){worker.shutdownNow();pairWorker.shutdownNow();super.onDestroy();}
}
